insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('guru-44663','course','Легендарный сервис и секреты продаж в ресторане',null,'{"id":"guru-44663","title":"Легендарный сервис и секреты продаж в ресторане","shortTitle":"Легендарный сервис и секреты продаж в ресторане","coverLabel":"Легендарный сервис и секреты продаж в ресто…","description":"Работа с гостями и приёмы продаж в ресторане.","kind":"course","brand":"90-е","departments":["Зал","Бар","Кухня","Арт","Кальян","Руководитель"],"positions":[],"restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"Повышаем личные продажи","text":"Методы повышения среднего чека в ресторане\n\nСуществует много методов продаж и повышения среднего чека в ресторане. Поговорим о самых популярных из них.\n\nКивок «Салливана»\n\nЭтот метод заключается в следующем: предлагая гостю какое-либо блюдо или напиток, официант должен улыбнуться, медленно опустить голову вниз и поднять обратно, изображая таким образом утвердительный кивок. Согласно исследованиям, более 60% гостей неосознанно повторят согласный кивок и закажут предложенную официантом позицию.\n\nМетод «Елочки»\n\nЭтот метод построен на предложении альтернативы выбора. Наводящие вопросы, которые задает официант, должны разбивать меню или его разделы на части. При этом деление желательно производить поровну. «Вы хотите плотно пообедать или утолить легкий голод?», «Какое мясо вы предпочитаете: свинину, говядину, телятину, а может баранину?»\n\nВыясняем таким образом, что гость любит курицу, а в качестве гарнира отдает предпочтение рису, значит предлагаем ему позиции из меню, соответствующие его выбору, к примеру: отварной рис с фрикасе из курицы или фриттата с рисом и копчёной куриной грудкой. И вот уже перед гостем ограниченное количество позиций, из которых проще выбрать что-то определенное.\n\n﻿Безусловно целью такой беседы должна стать обоснованная рекомендация наиболее маржинального блюда. Но при этом у гостя создается впечатление, что это его выбор, ведь официант просто задавал правильные вопросы!\n\n«Апселлинг»\n\nПредложение более дорогой позиции из меню в качестве альтернативы.\n\nНапример, ваш гость хочет заказать пиво. Официант может предложить напиток из средней ценовой категории, который заказывают чаще всего, но лучше порекомендовать новое крафтовое пиво или более дорогой сорт. Когда гости хотят заказать два набора разных роллов, официант может предложить им сет, в котором будет много различных роллов, в том числе те, которые хотели заказать гости.\n\nЕсли же посетители заказывают просто 2 чашки чая, то официант может предложить им чайник с фирменным фруктовым чаем и т. д.\n\n«Кросс-селлинг»\n\nПродажа дополнительных позиций, расширение заказа.\n\nСуть этого метода в том, что официант предлагает попробовать дополнительные напитки, блюда или ингредиенты к блюдам. Это могут быть соусы к картофелю, рыбе или мясу, закуски к пиву, первое к основному блюду, топинг к мороженому или дополнительная начинка к пицце. Список можно продолжать очень долго, все зависит от профиля и ассортимента вашего заведения.\n\nРекомендации можно давать по ходу заказа, на его разных этапах. Например, официант может предложить гостям десерт к кофе или салат, пока готовится основное блюдо.\n\n“Даунселлинг”\n\nСуть данного метода в том, чтобы предложить гостю уменьшить порцию блюда для того, чтобы он захотел заказать еще что-нибудь. Таким образом повысится маржинальность вашего заказа. Например, ваша гостья заказывает тыквенный суп, а вы знаете, что порция этого супа очень большая, и после того, как она его доест, она уже не захочет никакие другие блюда. Соответственно, вы можете ей предложить заказать половину порции тыквенного супа и салат, или предложить в конце десерт, так вы увеличите чек и маржинальность вашего заказа.\n\nДополнительные предложения, “Допники”.\n\nКогда гость заказывает то или иное блюдо, вы тут же вспоминаете, что еще можно предложить к этому блюду, какие небольшие дополнительные опции вы можете еще дать гостю. Например, при заказе борща можно предложить сметану, хрен, горчицу, зеленый лук, пампушки, смалец, и так далее. Все это существенно повысит ваш средний чек.","images":["assets/remaining-courses/guru-44663-105991-0.jpg","assets/remaining-courses/guru-44663-105991-1.jpg","assets/remaining-courses/guru-44663-105991-2.jpg","assets/remaining-courses/guru-44663-105991-3.jpg","assets/remaining-courses/guru-44663-105991-4.jpg","assets/remaining-courses/guru-44663-105991-5.jpg"],"links":[],"id":"105991"},{"title":"Легендарный сервис","text":"Легендарный сервис\n\nКак известно, самое главное в ресторане - это кухня.\n\nОднако, плохой сервис способен уничтожить самую лучшую и вкусную кухню! И напротив, качественый, стабильный легендарный сервис может скрыть огрехи не очень хорошего повара. Так как же сделать так, чтобы сервис в нашем ресторане стал Легендарным?\n\nЧто же такое Легендарный сервис? Что такое сервис, про который гости рассказывают друг другу? Сервис, о котором ходит молва? Сервис, из-за которого гости возвращаются к вам и приводят с собой своих друзей в ресторан?\n\nСегодня я хочу рассказать вам одну известную историю. Молодая семья с маленьким ребенком отдыхала в отеле Ritz Karlton. Ребенок забыл там свою любимую игрушку Джошуа. Родители позвонили в отель и попросили, чтобы сотрудники отеля отправили эту игрушку к ним домой. Но эти сотрудники знали, что такое легендарный сервис! Они были на одном из тренингов известных гуру! И поэтому, родителей этого ребенка ожидал сюрприз, ну и конечно же, самого малыша.\n\nСотрудники отеля взяли Джошуа и провели для него отличный день. Точнее, они сделали фотографии того, как Джошуа прекрасно проводит время в их отеле. Ему сделали массаж в спа-центре и сфотографировали это. Джошуа загорал на пляже, и это тоже сфотографировали. Джошуа вместе с его друзьями, другими игрушками сидел на диване в холле этого прекрасного отеля и смотрел телевизор. С помощью Джошуа этот отель показал свои возможности -- что может делать гость в этом отеле, когда он там отдыхает. Они собрали фотографии, написали письмо с наилучшими пожеланиями, и отправили его в тот вечер, когда звонили родители, им на электронную почту. А следом отправили игрушку. Конечно, малыш и его родители до слез были тронуты тем, как сотрудники отеля творчески подошли к их просьбе. И они опубликовали это письмо в интернете, и в социальных сетях, и стали об этом рассказывать своим друзьям, а те своим, и сегодня каждый стотысячный человек планеты знает эту историю. А сотрудникам отеля это не стоило ни одной копейки!\n\nЯ хочу, чтобы сегодня, когда вы придете на работу, и какой-то гость попросит вас о помощи, вы задумались: “А что я могу сделать для гостя такого, чтобы завтра обо мне складывались легенды?”.\n\nУдачи вам, ребята!","images":["assets/remaining-courses/guru-44663-105992-0.jpg","assets/remaining-courses/guru-44663-105992-1.jpg"],"links":[],"id":"105992"}],"outline":[{"type":"lesson","title":"Повышаем личные продажи","lessonIndex":0},{"type":"test","title":"Повышаем личные продажи"},{"type":"lesson","title":"Легендарный сервис","lessonIndex":1},{"type":"test","title":"Легендарный сервис"}],"testIds":["95472","95473"]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('guru-44033','course','Кухни мира',null,'{"id":"guru-44033","title":"Кухни мира","shortTitle":"Кухни мира","coverLabel":"Кухни мира","description":"Знакомство с кухнями разных стран.","kind":"course","brand":"90-е","departments":["Кухня","Зал","Руководитель"],"positions":[],"restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"Французская кухня","text":"Эталон вкуса, которому завидует весь мир\n\nФранция — не просто страна с богатой кухней, а родина гастрономической культуры, которой восхищаются по всему миру. Здесь каждый приём пищи — это ритуал, искусство, стиль жизни. Именно французская кухня задала стандарты высокой гастрономии, а её влияние заметно в ресторанах и домах по всему миру.\n\nЧто делает французскую кухню великой?\n\n🥂 Культура наслаждения едой\n\nФранцузы не едят на бегу. Обед — это неспешное удовольствие, аперитив, несколько смен блюд, десерт и чашка кофе. Вкус — на первом месте.\n\n👨‍🍳 Haute Cuisine — высокая кухня\n\nФранция подарила миру изысканную подачу, тонкие вкусовые сочетания и легендарных шефов, таких как Поль Бокюз и Огюст Эскофье.\n\n🍷 Продукты высшего качества\n\nСыры (более 1600 видов!), вино, багеты, фуа-гра — все продукты имеют свою историю и стандарты терруара (terroir), определяющие их вкус.\n\n🎖 Первая кухня, признанная ЮНЕСКО\n\nФранцузская гастрономическая культура включена в список нематериального наследия ЮНЕСКО — это подтверждение её уникальности.\n\n🔥 Зависть и влияние на весь мир\n\nОт круассанов до шампанского — французские блюда стали символами роскоши и гастрономического совершенства.\n\nЧто попробовать, если ты хочешь ощутить вкус Франции?\n\n🍷 Биф Бургиньон – говядина, томлённая в красном вине с овощами и травами.\n\n🥖 Багет – хрустящий символ Франции, без которого не обходится ни один завтрак.\n\n🧀 Фондю – расплавленный сыр с кусочками хлеба, объединяющий всех за столом.\n\n🐓 Кок о ван – петух в вине, блюдо с глубокими вкусами и богатой историей.\n\n🥐 Круассан – утреннее удовольствие с чашкой ароматного кофе.\n\n🍮 Крем-брюле – нежный десерт с карамельной корочкой, покоряющий с первой ложки.\n\nФранцузская кухня — это не просто еда, а стиль жизни.","images":["assets/remaining-courses/guru-44033-103865-0.jpg","assets/remaining-courses/guru-44033-103865-1.jpg"],"links":[],"id":"103865"},{"title":"Итальянская кухня","text":"Почему весь мир обожает итальянскую кухню? 🍕\n\nКогда речь заходит об идеальной еде, первое, что приходит в голову — Италия. Пицца, паста, ризотто, морепродукты, лучшие вина и десерты… Кажется, эта страна создала кулинарное счастье.\n\n5 причин, почему итальянская кухня — это любовь с первого укуса\n\n🍅 Простота + качество\n\nИтальянцы не используют сложные рецепты — главное, чтобы продукты были свежими и натуральными. Лучшие блюда делают всего из 3-5 ингредиентов, но вкус просто взрывает мозг.\n\n🍕 Еда — это культура\n\nДля итальянцев еда — это ритуал и семейная традиция. Никаких перекусов на бегу: ужин — это долгий, приятный процесс с вином и разговором.\n\n🍝 Паста на 1000 способов\n\nВ Италии более 300 видов пасты, и каждая подаётся со своим соусом. Спагетти Карбонара, Лазанья, Паста Болоньезе — только классика, а сколько ещё региональных рецептов!\n\n🍷 Идеальное сочетание с вином\n\nЛюбое блюдо в Италии сопровождается вином. Белое — к морепродуктам, красное — к мясу и пасте, а Просекко можно пить просто так, потому что жизнь прекрасна.\n\n🍰 Десерты, которые невозможно не любить\n\n • Тирамису — нежный крем с кофе и какао.\n\n • Канноли — хрустящие трубочки с рикоттой.\n\n • Панна котта — лёгкий сливочный десерт.\n\nЧто попробовать, если хочешь ощутить вкус Италии?\n\n🥖 Брускетта — хрустящий хлеб с томатами и базиликом.\n\n🍝 Паста Карбонара — без сливок, только сыр, яйцо и панчетта.\n\n🍕 Пицца Маргарита — самая простая и самая вкусная.\n\n🥩 Оссобуко — томлёная телятина в белом вине.\n\n🍨 Джелато — лучшее мороженое в мире.\n\n✅ Главное правило итальянской кухни\n\nЧем проще — тем вкуснее.\n\nГлавное — качество продуктов и любовь к процессу. 🍷","images":["assets/remaining-courses/guru-44033-103866-0.jpg","assets/remaining-courses/guru-44033-103866-1.jpg"],"links":[],"id":"103866"},{"title":"Испанская кухня","text":"Еда, вино и культура, которые не спутаешь ни с одной другой страной🍷\n\nИспанская кухня — это про традиции, простоту и удовольствие от жизни. Если говорить об Испании, то в голове сразу всплывают паэлья, хамон, тапас и бокал вина на тёплой террасе. Но что ещё делает её уникальной?\n\n1. Испания — это паэлья 🥘\n\nГлавное блюдо страны. Её готовят на огромной сковороде и едят всей компанией прямо из неё. Самая классическая — паэлья по-валенсийски (с курицей и кроликом), но есть и версии с морепродуктами.\n\n2. Испания — это морепродукты 🦐\n\nИспанцы обожают креветки, осьминогов, мидии, кальмаров, лангустинов. Популярные блюда:\n\n • Пульпо а ла галега — варёный осьминог с паприкой и оливковым маслом.\n\n • Гамбас аль ахильо — креветки, обжаренные с чесноком.\n\n3. Испания — это хамон 🥩\n\nХамон — это культ. Самый элитный — хамон иберико, который делают из чёрных свиней, питающихся желудями.\n\n4. Испания — это вино и культура питья 🍷\n\nВ Испании пьют красное Риоха, белое Альбариньо, освежающее кава и сладкий херес. Главное правило — вино пьют медленно, смакуя, и всегда в компании. А темпранильо - это вообще идеальный вид удовольствия🤤\n\n5. Испания — это тапас и пинчос 🍢\n\nТапас — это маленькие закуски, которые принято заказывать сразу несколько. В Стране Басков популярны пинчос — мини-бутерброды с разными начинками.\n\n6. Испания — это чуррос и сладкие традиции 🍮\n\nИспанцы любят долго завтракать. Один из любимых утренних десертов — чуррос с горячим шоколадом.\n\nИспания — это не только еда, но и история, стиль и эмоции\n\n🏛 Гауди и сюрреалистичная архитектура\n\nБарселона — это город Антонио Гауди, создавшего уникальные шедевры: Саграда Фамилия, Парк Гуэль, Дом Бальо. Его здания похожи на сказочные замки с волнообразными линиями и мозаикой.\n\n🎭 Фламенко — танец страсти и эмоций\n\nИспания — это ритм кастаньет, гитара и невероятная энергетика фламенко. Это не просто танец, а искусство передавать чувства через движения.\n\n⚽ Футбол — вторая религия\n\nИспанцы живут футболом. «Барселона» и «Реал Мадрид» — это не просто клубы, это культ и многолетнее соперничество, которое разделяет страну на два лагеря.\n\n🌅 Испания — это солнце и бесконечные фиесты\n\nОни не работают, там не принято перетруждаться. \n\nИспанцы умеют наслаждаться жизнью. Здесь устраивают яркие праздники, карнавалы и фиесты, во время которых улицы превращаются в одну большую вечеринку.","images":["assets/remaining-courses/guru-44033-103867-0.jpg","assets/remaining-courses/guru-44033-103867-1.jpg","assets/remaining-courses/guru-44033-103867-2.jpg","assets/remaining-courses/guru-44033-103867-3.jpg","assets/remaining-courses/guru-44033-103867-4.jpg"],"links":[],"id":"103867"},{"title":"Японская кухня","text":"Вкус, доведённый до идеала 🍣🍵\n\nЯпония — это не просто еда, а искусство, философия и стремление к совершенству. Здесь не готовят просто для утоления голода — каждое блюдо проходит долгий путь отточенных техник, внимательного подбора ингредиентов и уважения к традициям.\n\nЯпонцы верят в кайдзен — непрерывное улучшение, поэтому всё, что здесь подают, — это результат многолетней практики и доведения вкуса до идеала.\n\nЧто делает японскую кухню уникальной?\n\n🍣 Минимум ингредиентов — максимум вкуса\n\nЯпонцы используют только самое необходимое, раскрывая естественный вкус продуктов. Важны не сложные соусы, а свежесть рыбы, правильный рис и умение подчеркнуть их сочетание.\n\n🔪 Совершенство в деталях\n\nЯпонские повара годами учатся нарезать рыбу, варить рис, готовить лапшу. Здесь нет места случайности — каждый этап отточен до идеала.\n\n🥢 Еда как искусство\n\nКрасивая подача — это часть культуры. Каждое блюдо оформляют так, чтобы оно радовало глаз и гармонировало с окружающей атмосферой.\n\n🍜 Уважение к сезонности\n\nВ японском меню всегда используются продукты по сезону. Весной — свежая зелень и рыба, летом — охлаждающие супы, осенью — грибы и корнеплоды, зимой — согревающий мисо и горячие бульоны.\n\nРобата — душа японской гастрономии 🔥\n\nРобата (или робатаяки) — это традиционный японский метод приготовления на углях, который пришёл от рыбаков острова Хоккайдо. Они жарили рыбу и овощи на открытом огне, сохраняя максимальный вкус и сочность.\n\n🍢 Как это выглядит?\n\n • Блюда готовятся на углях при невысокой температуре, что делает их ароматными и нежными.\n\n • Используются деревянные шпажки — похожие на якитори, но с более разнообразными ингредиентами.\n\n • В меню робаты можно найти рыбу, мясо, овощи, морепродукты и даже тофу.\n\n🔥 Почему это популярно?\n\nРобата — это не просто еда, а процесс. В ресторанах с робатой повара готовят прямо перед гостями, создавая атмосферу уюта и взаимодействия. Это похоже на японский аналог барбекю, но с тонкими вкусами и японской эстетикой.\n\nСаке — символ японской культуры 🍶\n\nЯпония — это не только чайная церемония, но и культура саке. Этот напиток — не просто алкоголь, а часть ритуалов и традиций.\n\n🍶 Как пьют саке?\n\n • Подавать его можно горячим или охлаждённым, в зависимости от сорта.\n\n • Наливают саке не себе, а друг другу — это жест уважения.\n\n • Пьют маленькими глотками, чтобы прочувствовать вкус.\n\nСаке сопровождает важные события: от праздников до деловых встреч. Это не про количество, а про гармонию и наслаждение моментом.\n\nДесерты Японии — искусство сладкого вкуса 🍰🍡\n\nЯпонские сладости не просто вкусные — они безупречно приготовлены. Здесь не делают десерты просто сладкими. Они должны быть лёгкими, нежными и элегантными.\n\n🍵 Матча-десерты – зелёный чай матча используют в мороженом, пирожных, шоколаде и даже тирамису. Его насыщенный вкус делает десерты глубокими и многослойными.\n\n🍡 Моти (Mochi) – рисовые колобки с начинками (красная фасоль, зелёный чай, крем). У них необычная, слегка жевательная текстура, которая покоряет с первого укуса.\n\n🍮 Пудинг Пурин (Purin) – японская версия крем-карамели. Нежный, тающий во рту, с идеальным балансом сладости.\n\n🍈 Торты и выпечка – японские чизкейки и бисквиты невесомые как облако. Всё потому, что японцы довели до совершенства баланс воздушности и текстуры.\n\n🍫 Кит-Кат с сотнями вкусов – в Японии самый богатый выбор Кит-Катов: с васаби, саке, манго, бататом и даже сладкой фасолью. Это стало культовой частью японской гастрономии.\n\nПочему в Японии всё самое вкусное? 🤯\n\n✅ Потому что доводят всё до идеала – японские шефы могут годами оттачивать одно блюдо, пока оно не станет совершенным.\n\n✅ Качество – важнее количества – лучше меньше, но идеально.\n\n✅ Сезонность и свежесть – всё подбирается по времени года, чтобы продукты были на пике вкуса.\n\n✅ Внимание к деталям – форма, текстура, температура, даже способ подачи имеют значение.\n\n✅ Осознанное питание – японцы наслаждаются каждым кусочком, ведь еда – это ритуал и искусство.","images":["assets/remaining-courses/guru-44033-103870-0.jpg","assets/remaining-courses/guru-44033-103870-1.jpg","assets/remaining-courses/guru-44033-103870-2.jpg","assets/remaining-courses/guru-44033-103870-3.jpg","assets/remaining-courses/guru-44033-103870-4.jpg","assets/remaining-courses/guru-44033-103870-5.jpg","assets/remaining-courses/guru-44033-103870-6.jpg","assets/remaining-courses/guru-44033-103870-7.jpg"],"links":[],"id":"103870"},{"title":"Русская кухня","text":"Россия: хлеб, душа, застолья\n\nРоссия — это страна, где еда всегда была чем-то большим, чем просто пища. Это ритуал, уважение к сезону, к гостю, к традиции. В центре — грибы, региональная сезонность, печь и настоящее застолье.\n\nХлеб — всему голова.\n\nБез хлеба у нас не едят. Ржаной, бородинский, на закваске — это не просто продукт, это символ уюта, тепла и уважения. Хлеб-соль — знак гостеприимства. Отломить краюху, намазать маслом, посыпать солью — и ты уже дома.\n\nГрибы — гордость русской кухни.\n\nБелые, подосиновики, маслята, лисички… Их жарят со сметаной, варят похлёбки, солят и сушат. Осень — это корзинка, лес, тишина и запах грибов. Умение готовить грибы — как народная суперсила.\n\nСезонность — как правило\n\nВесной — щавель и крапива. Летом — огурцы, укроп, ягоды. Осенью — капуста, корнеплоды, грибы. Зимой — соленья, квашеная капуста, варенья. Кухня следует за природой: что дала — то и на столе.\n\nПечь — сердце дома\n\nТолько в России еда томилась в печи: щи, каши, пироги, картошка, грибы. Вкус из печи — тёплый, глубокий, как объятие. Она не только кормила, но и грела дом, сушила травы и ягоды. А главное — на ней спали, укрывшись половичком или шубой. Это не просто утварь — это целый мир.\n\nРусские блюда — простые, но с душой:\n\n— Щи кислые или из свежей капусты\n\n— Пельмени — уральская классика\n\n— Кулебяка — пирог-слоёный роман\n\n— Томлёные каши с маслом в глиняных горшках\n\n— Солянка, рассольник, окрошка — ярко, сытно, по-настоящему\n\n— Блины с икрой, мёдом, творогом\n\n— Печёные яблоки, гречка с грибами, вареники с вишней\n\nЩи да каша — пища наша\n\nРусская кухня — это не про спешку. Это про заботу. Уважение. Про то, чтобы собраться за столом и остаться дольше. Чтобы было вкусно — нужно не только соль, но и душа.\n\nУ каждой земли — свой вкус\n\nКарелия — калитки с картошкой. Урал — пельмени и солёные грузди. Поволжье — рыба, шурпа, лепёшки. Кавказ — мясо, травы, лаваш. Сибирь — строганина, кедровые орехи, морошка. Приморье — морская рыба и дикоросы. Русская кухня — это как карта вкусов: широкая, разная, настоящая.\n\nЗастолье — больше, чем еда\n\nСтол ломится не от роскоши, а от щедрости. Тосты, душевные разговоры, чай из самовара. Посиделки до ночи — как мини-праздник. Главное не то, что на столе, а кто за ним сидит.\n\nРусская кухня — это не про пафос. Это про вкус, корни, тепло. Про дом, к которому хочется возвращаться. Всегда.","images":["assets/remaining-courses/guru-44033-105728-0.jpg","assets/remaining-courses/guru-44033-105728-1.jpg","assets/remaining-courses/guru-44033-105728-2.jpg","assets/remaining-courses/guru-44033-105728-3.jpg","assets/remaining-courses/guru-44033-105728-4.jpg","assets/remaining-courses/guru-44033-105728-5.jpg","assets/remaining-courses/guru-44033-105728-6.jpg","assets/remaining-courses/guru-44033-105728-7.jpg","assets/remaining-courses/guru-44033-105728-8.jpg"],"links":[],"id":"105728"}],"outline":[{"type":"lesson","title":"Французская кухня","lessonIndex":0},{"type":"lesson","title":"Итальянская кухня","lessonIndex":1},{"type":"lesson","title":"Испанская кухня","lessonIndex":2},{"type":"lesson","title":"Японская кухня","lessonIndex":3},{"type":"lesson","title":"Русская кухня","lessonIndex":4},{"type":"test","title":"Тест по кухням мира"}],"testIds":["94526"]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('guru-44607','course','Всё о винах🍷',null,'{"id":"guru-44607","title":"Всё о винах🍷","shortTitle":"Всё о винах🍷","coverLabel":"Всё о винах🍷","description":"Красные и белые сорта, розовые и игристые вина, сочетания с блюдами.","kind":"course","brand":"90-е","departments":["Зал","Бар","Кухня","Арт","Кальян","Руководитель"],"positions":[],"restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"Красные сорта","text":"Красные вина богаты дубильными веществами и антоцианами, потому что мацерация виноградного сусла происходит совместно с кожурой и косточками ягод. Этот процесс длится от 4-х до 10 дней. Далее следует фильтрование, прессование и созревание напитка. Некоторые благородные красные вина дополнительно выдерживают в дубовых бочках, где они обретают насыщенный характер и богатый аромат. К таким винам можно отнести Гамэ, Пино Нуар, Мальбек, Гренаш и Мерло.\n\nКак и все виды алкогольных напитков красные сухие вина требуют особого подхода и сервировки. Наилучшей температурой для употребления напитков считается 20-24 С. При этом важно откупорить бутылку за час до того, как вы планируете разливать его по бокалам, что позволит вину начать дышать. Это правило не распространяется на винтажные вина. Их стоит употреблять сразу же после открытия бутылки.\n\nЧто касается закусок. Сухие вина отлично сочетаются с мясными блюдами. Это может быть баранина, дичь, домашняя птица или же шашлык. Шницели, котлеты и антрекоты — тоже хороший выбор. Терпкие сыры, фрукты и легкие десерты тоже подойдут в качестве закуски.\n\nСовершенно неподходящими блюдами для красного сухого вина являются рыбные консервы и шоколад. Эти продукты перебьют вкус напитка и не позволят насладиться его вкусом на все 100%.\n\nБазовые красные сорта винограда 🍇\n\nЧто такое виноград? Мякоть, кожица, сок, косточки.\n\nКак из этого получается то, что является частью культуры каждого народа? Очевидно, что так просто в этом не разберешься.\n\nПредлагаем вам пройтись по базовым сортам красного винограда. Почему сорт так важен?\n\nСамые главные, основные характеристики вина обусловлены именно сортом винограда.\n\nНе имея представления об основных особенностях каждого сорта, вы не сумеете правильно сравнивать вина между собой, а значит выбрать своего любимчика. Когда вам понравится какой-то сорт, вы начнете сравнивать вина между собой из разных уголков мира. Появятся любимые страны, регионы, виноделы. И во главе этого будет стоять сорт винограда.\n\nДавайте пофантазируем: что было бы, если бы виноград был мужчиной?\n\n🍇 Каберне Совиньон. Популярный, узнаваемый красавчик. Его любят все, везде хорош, не хватает элегантности, но с ним мало проблем;\n\n🍇Гарнача/Гренаш нуар. Ходячий секс. Немного неотесанный, слишком простой. Зато какой горячий и соблазнительный;\n\n🍇Мерло. С ним легко и комфортно. Он такой мягкий, демократичный. С ним можно договориться, готов быть на вторых ролях;\n\n🍇Неббиоло. В молодости такие мужчины слишком агрессивны, вспыльчивы. Понять их можно только в зрелости;\n\n🍇Пино Нуар. Истинный джентльмен. Самовлюбленный, капризный, ранимый. С тонкой душевной организацией, девушек манят такие;\n\n🍇Санджовезе. Симпатичный, стильный итальянец. Хороший спутник и приятный компаньон;\n\n🍇Сира/Шираз. Экспрессивный красавчик, который влюбляет в себя с первого взгляда. Яркий, понятный характер;\n\n🍇Зинфандель. Типичный американец;\n\n🍇Темпранильо. Пожалуй, этот парень понравится всем. Сочетает самоуверенность, элегантность при отсутствии сложности и заморочек.\n\nВ таком шуточном формате мы прошлись по девяти основным сортам красного винограда.\n\nТемпранильо - красный сорт винограда испанского происхождения\n\nРазберём подробно один из наших любимых сортов🍇\n\nВсегда будет интересный, понятный букет ароматов☕️\n\n🍇Темпранильо составляет основу многих лучших вин Испании и Португалии☝️почти каждое вино из Риохи и Рибера дель Дуэро строится на базе Темпранильо\n\n🍇Лозы Темпранильо успешно культивируются и в Новом Свете, в частности, в Калифорнии, Австралии и Аргентине\n\n🍇Хотя Темпранильо не обладает ярко выраженным букетом, в винах с его участием можно обнаружить довольно широкую гамму ароматов🙌: от клубники, чёрной смородины и вишни до чернослива, шоколада и табака\n\n🍇темпранильо + американский дуб = лучшие друзья👯\n\n🍇темпранильо это сорт с невысоким уровнем кислотности\n\n🍇Рибера дель Дуэро - именно здесь темпранильо лучше всего раскрывает свой потенциал – в условиях, когда жаркие солнечные дни позволяют его толстокожим ягодам полностью вызреть, а холодные ночи дают возможность сохранить естественный кислотный баланс🥂\n\nХорошо подходит к легким закускам, мясным блюдам без тяжелых соусов. Хорошее вино для медитации*\n\n*вино для медитации - это вино которое хорошо само по себе, его не обязательно дополнять едой. Берем бутылку, открываем, наслаждаемся🤤\n\nЧто можем сказать о других сортах?\n\n🍇Каберне Совиньон — король Бордо и один из самых распространённых сортов мира🌍. Основной компонент в купажах Бордо, также успешно культивируется в Калифорнии, Чили и Австралии. Высокие танины, ароматы чёрной смородины, зелёного перца и кедра. Идеально сочетается с французским дубом, который добавляет ноты ванили и дыма.\n\n🍇Мерло — «мягкий гигант» Бордо, часто купажируется с Каберне🌿. Вина с бархатистой текстурой, нотами сливы, чёрной вишни и шоколада. В теплом климате (Калифорния, Чили) приобретает джемовые оттенки. Низкие танины делают его идеальным для новичков. \n\n🍇Пино Нуар — капризный сорт Бургундии с тонкой кожурой🍒. Ароматы красной вишни, земляники, грибов и влажной земли. В прохладном климате (Орегон, Новая Зеландия) сохраняет элегантность и минеральность. \n\n🍇Неббиоло — «король Пьемонта», основа Бароло и Барбареско👑. Высокая кислотность, ароматы вишни, розы, кожи и трюфеля. Требует длительной выдержки для смягчения танинов. Лучшие образцы — из коммун Серралунга и Монфорте. \n\n🍇Гарнача (Гренаш) — основа испанских вин Приората и ключевой сорт Южной Роны🍷. Даёт вина с высоким алкоголем, мягкими танинами и ароматами малины, клубники и пряностей. В розовых винах Прованса и Наварры раскрывается яркой свежестью. \n\n🍇Санджовезе — сердце Тосканы, основа Кьянти и Брунелло ди Монтальчино🇮🇹. Высокая кислотность, ароматы кислой вишни, сушёных трав и кожи. В купажах «Супертоскан» сочетается с Каберне Совиньон. \n\n🍇Зинфандель — «американская классика» с джемовыми ароматами ежевики, лакрицы и корицы. Старые лозы Калифорнии (например, Dry Creek Valley) создают вина с высокой концентрацией и алкоголем. Часто выдерживается в американском дубе. \n\n🍇Шираз (Сира) — австралийская легенда с мощными танинами и нотами чернослива, перца и дыма🔥. В долине Роны (Франция) даёт более сдержанные вина с минеральными акцентами. Отличается от Сира плотностью и терпкостью.","images":["assets/remaining-courses/guru-44607-105819-0.jpg","assets/remaining-courses/guru-44607-105819-1.jpg","assets/remaining-courses/guru-44607-105819-2.jpg","assets/remaining-courses/guru-44607-105819-3.jpg","assets/remaining-courses/guru-44607-105819-4.jpg","assets/remaining-courses/guru-44607-105819-5.jpg","assets/remaining-courses/guru-44607-105819-6.jpg","assets/remaining-courses/guru-44607-105819-7.jpg"],"links":[],"id":"105819"},{"title":"Белые сорта","text":"Белые вина изготавливают путем сбраживания чистого виноградного сока. Важным условием производства является то, что первый этап включает прессование и только потом – брожение виноградного сусла. Это позволяет не допускать контакт основного материала с красящими элементами (кожурой, косточками и прочими твердыми частями грозди). При соблюдении необходимых условий возможно изготовить белое вино даже из некоторых красных сортов винограда, например, Пино Нуара.\n\nБелые вина отличаются тонким и нежным вкусом, а их аромат легкий и изменчивый. Они сочетаются с разнообразными продуктами: сырами, птицей, белой рыбой, грибами, морепродуктами, овощами и десертами. Основное правило, которому нужно следовать, при выборе гастрономического сопровождения к белому вину — блюдо не должно обладать насыщенным копченым, кислым или острым вкусом. Такая пища не даст в полной мере ощутить нежные фруктовые и цветочные нотки аромата белого вина, его приятную кислинку и свежесть во вкусе.\n\nЗапоминаем популярные белые сорта🥂\n\nПочему разбираться в сортах винограда так важно? От сорта во многом зависит стиль вина. Чтобы понять, какое вино вам нравится, нужно попробовать все популярные сорта. Возможно, вы окажетесь любителем кислотных фруктовых вин, а может вам по душе выдержанные в дубе округлые вина.\n\nКаждый сорт имеет уникальный, яркий и очень узнаваемый набор характеристик. В прошлом уроке мы сравнили мужчин с красными сортами винограда, здесь хотим сравнить женщин с белыми. Такая задумка не случайна.\n\nБелые сорта винограда гораздо изысканнее и сложнее. Как и женщины, преподносят сюрпризы, удивляют и каждый раз раскрываются с разных сторон. Для того чтобы разобраться в белых винах нужно больше времени и сил.\n\nИтак, включаем фантазию.\n\n🥂 Miss Шардоне. Это девушка — звезда. Мэрилин Монро в мире вин. С округлыми, сексуальными формами. Мужчины хотят побыть в ее обществе. От нее пахнет карамелью и ванилью.\n\n🥂 Miss Гевюрцтраминер. Хочет нравиться всем и сразу, поэтому использует все способы обольщения. Иногда это кажется слишком нелепым и представляется пародией на изысканность. Но стоит ей расслабиться и стать собой — вскружит голову!\n\n🥂 Miss Рислинг. Эта девушка без особого труда получает высшие оценки общества. У нее успешная карьера, всего добивается сама. Яркая и привлекательная, ей сложно найти пару так как привыкла все делать сама.\n\n🥂 Miss Совиньон Блан. Звонкая, стройная блондинка. Общительная, харизматичная, часто в окружении мужчин. В зависимости от настроения, пахнет крыжовником и черной смородиной или экзотическими фруктами.\n\n🥂 Miss Пино Гри (Пино Гриджио). Лолита среди вин. Очаровательная, юная красотка, которой пока не хватает харизмы и изюминки.\n\n🥂 Miss Вионье. Немного капризная, чувствительная, мягкая натура. Таких девушек мало, они созданы для любви и всегда оставляют шлейф абрикосов и весенних цветов.\n\n🥂 Miss Глера. (Prosecco). Легкая на подъем, выступает за любой праздник и вечеринку. Готова танцевать до утра, а после устраивать деловой завтрак с коллегами.\n\nРислинг\n\n🍇Родина сорта - Германия, там его называют винным королем.\n\n🍇входит в \"золотую тройку\" белых сортов, наравне с шардоне и совиньон бланом. Рислинг считается одним из самых аристократичных сортов винограда.\n\n🍇лучшие вина получаются одновременно бодрящими и возвышенными, ароматными и строгими.\n\n🍇рислинг ценят за дружелюбие к еде, более сладкие рислинги, прекрасное сопровождение к острым блюдам, например азиатская кухня. Сухие (Trocken) рислинги хорошо сочетаются с легким мясом и рыбой.\n\n🍇ценят за разнообразие вкусов - благодаря этой самой высокой кислотности даже десертные версии остаются свежими и не кажутся приторными.\n\n🍇любят за богатую и необычную ароматику!\n\n🍇рислинг максимально выражает терруар:\n\n👉Эльзас, Франция: этот крошечный французский регион одержим сухим рислингом и имеет 51 виноградник класса гран крю, где делают несколько действительно драгоценных вин\n\n👉Niederösterrich, Aвстрия: здесь предпочитают более сухие стили рислинга\n\n👉Южная Австралия: долины Клэр и Иден в Южной Австралии делают рислинги с долей извести во вкусе, в возрасте они приобретают дымные дизельные ноты\n\n👉Вашингтон, Нью-Йорк, Британская Колумбия и Ниагарский откос: лучшие североамериканские сухие рислинги\n\n👉Германия: здесь царит мозельский рислинг\n\n👉Пфальц — это про минералы\n\n👉Рейнгау - вина высшей категории ВА и ТВА\n\n👉Рейнхессен-свежая, сочная, фруктовая бомба💣\n\nЧто можем сказать о других сортах вина?\n\n🍇 Гевюрцтраминер\n\nРодом из Эльзаса, Франция. Сорт-«хамелеон»: от сухих до сладких вин с ароматами розы, личи и пряностей.\n\nЛучшие вина — плотные, с экзотической ароматикой и долгим послевкусием. Идеальны к азиатской кухне, сырам мюнстер и пряным блюдам.\n\nЦенят за яркость: даже в сухих версиях чувствуются ноты имбиря и мускуса.\n\n👉 Терруар:\n\nЭльзас, Франция: Гран Крю (минеральные и цветочные вина).\n\nПфальц, Германия: Легкие фруктовые версии.\n\nНовая Зеландия: Экзотические акценты. \n\n🍇 Совиньон Блан\n\nРодина — долина Луары, Франция. Входит в ту же «тройку», что Шардоне и Рислинг.\n\nЛучшие вина — бодрящие, с нотами свежескошенной травы, грейпфрута и крыжовника. Сухие версии из Новой Зеландии — эталон стиля.\n\nЦенится за кислотность: даже десертные вина (например, Сотерн) сохраняют свежесть. Сочетается с козьими сырами, устрицами и овощными тартарами.\n\n👉 Терруар:\n\nСансер, Франция: Кремневые ноты.\n\nМальборо, Новая Зеландия: Интенсивный тропический букет.\n\nКалифорния, США: Выдержка в дубе. \n\n🍇 Шардоне\n\nРодина сорта — Франция, Бургундия. Входит в «золотую тройку» белых сортов, наравне с Рислингом и Совиньон Бланом.\n\nЛучшие вина сочетают элегантность и насыщенность: от минеральных вин Шабли до маслянистых калифорнийских версий с нотами ванили и ананаса.\n\nЦенится за универсальность: сухие вина идеальны с морепродуктами и курицей, а выдержанные в дубе — с жирной рыбой и сливочными соусами.\n\nЛюбят за многогранность: в прохладном климате — яблоко и цитрусы, в теплом — тропические фрукты.\n\n👉 Терруар:\n\nБургундия, Франция: Шабли (минеральность), Мёрсо (богатство).\n\nКалифорния, США: Напа и Сонома (тропические ноты).\n\nМаргарет Ривер, Австралия: Баланс кислоты и фруктовости. \n\n🍇 Вионье\n\nРодом из долины Роны, Франция. Редкий сорт с ароматами персика, абрикоса и акации.\n\nЛучшие вина — плотные, с кремовой текстурой. Часто выдерживают в дубе, добавляя ноты ванили. Сочетаются с жирной рыбой, тайской кухней и мягкими сырами.\n\nЦенят за экзотику: даже в сухих винах чувствуется «солнечный» характер.\n\n👉 Терруар:\n\nКондриё, Франция: Эталонные вина с террасных виноградников.\n\nКалифорния, США: Мощные и фруктовые.\n\nКубань, Россия: Эксперименты с оранжевыми винами.\n\n🍇 Глера\n\nИтальянский сорт, основа Просекко. Вина — игристые, с нотами зеленого яблока, груши и белых цветов.\n\nЛучшие образцы — из Вальдоббьядене: свежие, с тонкими пузырьками. Идеальны как аперитив или к легким десертам.\n\nЦенят за доступность и праздничный характер.\n\n👉 Терруар:\n\nВальдоббьядене, Италия: Минеральные и элегантные.\n\nТревизо, Италия: Фруктовые и простые. \n\n🍇 Пино Гриджио (Пино Гри)\n\nИтальянская версия «серого» Пино. Легкие вина с нотками зеленого яблока, груши и цитрусов.\n\nЛучшие образцы — из Трентино-Альто-Адидже: свежие, с миндальным финишем. Идеальны для аперитива или легких салатов.\n\nЦенят за доступность: вина редко выдерживают в дубе, чтобы сохранить фруктовую чистоту.\n\n👉 Терруар:\n\nАльто-Адидже, Италия: Минеральные и свежие.\n\nЭльзас, Франция: Более насыщенные, с медовыми нотами.\n\nОрегон, США: Умеренная кислотность.","images":["assets/remaining-courses/guru-44607-105820-0.jpg","assets/remaining-courses/guru-44607-105820-1.jpg","assets/remaining-courses/guru-44607-105820-2.jpg","assets/remaining-courses/guru-44607-105820-3.jpg"],"links":[],"id":"105820"},{"title":"Розовые Вина","text":"Всё, что нужно знать о розовых винах 🌸\n\nРозовые вина – это идеальный компромисс в мире виноделия. Они не такие танинные и мощные, как красные, но при этом более округлые и структурированные, чем легкие белые. Их секрет кроется в методах производства, которые позволяют получить тот самый «поцелуй» цвета и аромата.\n\nСуществует два самых распространенных способа изготовления розе:\n\n1. Кровопускание (Saignée)\n\nМетод, при котором ягоды несколько часов подвергают медленному прессованию. Сок успевает слегка окраситься в розовый цвет, после чего его сливают и отправляют на ферментацию. Такие вина получаются деликатными, легкими, с нежным цветочно-ягодным ароматом. Это вина для тех, кто ценит изящество.\n\n2. Кратковременная холодная мацерация\n\nВиноградное сусло в течение суток выдерживают на мезге (кожуре) при холодной температуре. Брожение не успевает начаться, но красящий пигмент из кожицы переходит в сок. Далее виноград прессуют, а полученный розовый сок ферментируют как белое вино. Такой стиль называют «винным». Напиток получается насыщенным по цвету, с мягким объемным вкусом и сочным ароматом красных ягод. Яркий пример – французское Travel Rose из Долины Роны, которое часто называют «Королем розовых вин».\n\nИдеальный партнер: с чем пить розовое? 🍷🥗\n\nРозовые вина — настоящие универсалы. Их суперспособность — сочетаемость с огромным количеством блюд. Почему? У них нет высокой танинности красных вин, но при этом они более полнотелые, чем белые.\n\nИм подходят:\n\nГорячие первые и вторые блюда\nСалаты\nДесерты\nМорепродукты и азиатская кухня\n\nГлавное правило: розовое вино любит, чтобы его пили легко, не перегружая тяжелыми соусами.\n\nБазовые стили розового: если бы розовые вина были девушками 👩🕺\n\nКак и в случае с красными сортами, стиль розового вина можно описать через характер. Давайте пофантазируем.\n\nРозе, сделанное методом «кровопускания». Легкая, воздушная кокетка. Ее появление всегда праздник. С ней просто, весело и не нужно ничего сложного. Идеальна для вечеринок.\nРозе, сделанное методом холодной мацерации. Уверенная в себе женщина. У нее есть характер, глубина и насыщенный внутренний мир. С ней интересно вести долгие беседы за ужином.\nПример для изучения: Vinho Verde Diario Rosado\n\nРазберем конкретное вино, чтобы понять, как теория превращается в практику. Перед нами яркий представитель португальского стиля.\n\n🍷 Вино: Vinho Verde Diario Rosado\n\nСтрана, регион: Португалия, Винью Верде («Зеленое вино» — молодое вино, которое пьют в первый год после урожая)\n\nСахар: Полусухое\n\nКрепость: 10% (легкое, как и подобает региону Винью Верде)\n\nОбъем: 0,75 л.\n\n🍇 Сортовой состав\n\nВиноград для этого вина — это аутентичная португальская смесь:\n\nЭшпадейру (65%) – основа, дает фруктовость и свежесть.\nВиньяо (15%) – придает цвет и легкую танинную структуру.\nАмарал (10%) и Боррасал (10%) – добавляют сложности и кислотности.\n\n🏭 Способ производства\n\nУрожай собирается частично вручную, частично механизированно. После доставки на винодельню виноград прессуется и проходит мацерацию на кожице (чтобы получить нежный цвет). Ферментация проходит при строго контролируемой температуре 14–16 °С в течение 17–22 дней в емкостях из нержавеющей стали. Перед бутилированием вино недолго выдерживается на тонком осадке, чтобы стать чуть более округлым.\n\n👃 Дегустационные характеристики\n\nЦвет: нежный, ярко-розовый.\nАромат: ярко выраженный, наполнен фруктово-ягодными и цветочными оттенками. Чувствуется клубника, малина и легкие ноты полевых цветов.\nВкус: мягкий, очень приятный, с оттенками красных фруктов и ягод. Послевкусие свежее и элегантное.\n\n🍽️ Гастрономия\n\nЭто универсальное вино. Оно идеально подходит к:\n\nСалатам\nРыбе и морепродуктам\nБелому мясу и блюдам из дичи\nБлюдам азиатской кухни\n\n💡 Стилистика\n\nЭто аперитивное, фруктовое, нежное и мягкое вино. Оно создано для того, чтобы радовать своей простотой и свежестью. Его не нужно долго «раскуривать» или выдерживать в погребе — лучше выпить сейчас, наслаждаясь моментом.\n\nРезюме: Розовые вина — это радость без правил. Они дарят нам сочность красных ягод и свежесть белого вина. А Vinho Verde Diario Rosado — это идеальный вход в этот мир: легкий, понятный и невероятно гастрономичный.","images":["assets/remaining-courses/guru-44607-123999-0.jpg","assets/remaining-courses/guru-44607-123999-1.jpg"],"links":[],"id":"123999"},{"title":"Игристые вина","text":"Игристые вина насыщаются углекислым газом в процессе дрожжевой ферментации в герметичной емкости. Два наиболее распространенных метода производства игристого вина называются «традиционный» и «резервуарный» или как его еще называют метод Шарма Мартинотти.\n\n \n\nТрадиционным методом (также называемым Капским, классическим, бутылочным или технологией Шампенуаза) изготавливаются премиальные игристые вина: французское шампанское и креман, испанская кава и итальянская франчакорта, а также некоторые сорта немецкого секта. Он подразумевает вторичную ферментацию в бутылке, является достаточно трудоемким и затратным способом производства.\n\nПерляж: Непрерывные цепочки мелких пузырьков, давление 6–7 атм. внутри бутылки.\n\n \n\nПо технологии Шарма производится большинство итальянских вин, включая просекко и ламбруско. Основное отличие от классического способа заключается в том, что базовое вино на стадии тиража помещается не в бутылку, а в резервуар (танк) из нержавеющей стали. По завершении вторичной ферментации напиток фильтруется, затем в него добавляется сахарный раствор. Напиток разливается по бутылкам без дополнительной выдержки.\n\nПерляж: Искристые пузырьки среднего размера, давление 2–4 атм. внутри бутылки.\n\n🍾 Популярные стили игристых\n\nИгристые вина делают практически в каждом винодельческом регионе мира, поэтому географические индикаторы есть в названии или подразумеваются правилами апелласьона.\n\n🥂 Шампанское (Champagne) – производится классическим методом в регионе Шампань. Три главных сорта – пино нуар, шардоне и менье. Выдержка для немиллезимных вин составляет не менее 15 месяцев, и 12 из них они должны провести на осадке. Для миллезимных – 3 года, но хорошие производители часто увеличивают этот срок.\n\n🥂 Креман (Cremant) – французское игристое, которое делают с классическим методом за пределами Шампани. Сортовой состав и требования к выдержке отличаются в зависимости от региона.\n\n🥂 Франчакорта (Franciacorta) – итальянская родственница шампанского родом из Ломбардии. Игристое производят классическим методом, используя пино нуар, шардоне и пино блан. Выдержка – не менее 18 месяцев.\n\n🥂 Кава (Cava) – испанское игристое, сделанное классическим методом из автохтонных сортов макабео, щарелло и парельяда. Выдержка составляет не менее 9 месяцев.\n\n🥂 Кап классик (Cap Classique) – так обозначают вина, сделанные классическим методом в ЮАР. Минимальная выдержка на осадке для них составляет 12 месяцев.\n\n🥂 Просекко (Prosecco) – итальянское игристое родом из Венето или Фриули-Венеции-Джулии, которое делают с помощью метода Шарма из сорта глера. Требований к выдержке нет. У просекко найдется очень много игристых братьев по методу в самых разных уголках планеты.\n\n🥂 Зект (Sekt) – немецкое игристое, которое делают как традиционным, так и резервуарным методом. Как правило, в основе ассамбляжей фигурирует флагманский для Германии рислинг.\n\nА мануал об игристых винах ты можешь найти в разделе Библиотека - Винная карта 😉🍷\n\nСабраж — открытие бутылки ударом 🍾\n\nSabrage — раскупоривание саблей.\n\nОткрытие бутылки шампанского ударом бокала для вина. Ударом твёрдым предметом шампанское открывают во время пышных церемоний. По-французски эта техника называется «sabrage» (фр. sabre — сабля). Сабля, или иной твёрдый предмет, скользит вдоль тела бутылки по направлению к горлышку.","images":["assets/remaining-courses/guru-44607-105821-0.jpg","assets/remaining-courses/guru-44607-105821-1.jpg"],"links":[],"id":"105821"},{"title":"Сочетание вин с блюдами 🍽️","text":"Учись читать вкус — и сразу советуй напиток 🍷✨\n\nЗапомни пару простых связок — и ты уже не просто официант, а гастро-наставник за столом.\n\nЭто не про сомелье — это про уверенность в предложении.\n\n1. Лимон = Совиньон Блан 🍋\n\nЛюбое блюдо с лимоном — салат, рыба, креветки, авокадо, курица.\n\nСовиньон подчёркивает кислоту, освежает, делает вкус чище.\n\nПример: салат с лимонной заправкой? Говори: «Совиньон — прям в тему!»\n\n2. Грибы = Пино Нуар 🍄\n\nЕсли в блюде есть грибы (шампиньоны, вешенки, крем-соус) — пино нуар даёт мягкую глубину, не перебивает вкус.\n\nПример: паста с грибами, жульен, стейк с грибным соусом — «Пино отлично поддержит землистость грибов».\n\n3. Универсальный солдат = Игристое и розовое 🥂\n\nЕсли сомневаешься — игристое всегда в кассу. Оно освежает, подчёркивает вкус, не спорит с едой.\n\nРозовое — работает и с мясом, и с рыбой.\n\nА розовое игристое — идеально под жирное, солёное, немного острое.\n\nПример: картошка, сыр, куриные крылья, бургеры — отлично идут с розовым брютом.\n\n4. Десерты = сладкие напитки с характером 🍰🥂\n\nГлавное правило: напиток должен быть слаще десерта. Тогда вкус не потеряется, а наоборот — раскроется.\n\n✔️ Под десерты отлично заходят:\n\n— сладкие вина,\n\n— портвейны,\n\n— ликёры,\n\n— десертные коктейли.\n\nВ нашем случае всё, что сладкое.\n\nПримеры:\n\n— Три шоколада, банка-тирамису, эспрессо мартини — идеальная связка.\n\n— Мусс маракуйя + Мистер Жасмин — освежающе, с балансом кислинки и сладости.\n\n❗И не забывай: игристое всегда можно рекомендовать, когда блюдо несложное и когда сомневаешься в выборе напитка. \n\nВино с блюдами, которые приправленные травами\n\n🌿Тимьян + каберне совиньон и пино гриджио. Тимьян обладает ярким ароматом и острым пряным вкусом, часто используется при приготовлении мяса или рыбы. Каберне совиньон и пино гриджио идеально подчеркивают вкусовые нюансы блюда.\n\n🌿Розмарин + шираз и шардоне. Неповторимый аромат и нежный вкус приправы сделает абсолютно любое блюдо запоминающимся, а вино отлично будет сочетаться с блюдами.\n\n🌿Эстрагон + шираз и шардоне. Аромат и вкус приправы раскрывается в кислых блюдах. Шираз и шардоне прекрасна сгладят кислоту, если блюдо кажется вам слишком кислым.\n\n🌿Шалфей + пино нуар и рислинг. Шалфей - это душистая пряность с ярким вкусом и ароматом, которая способна затмить любое блюдо. Пино нуар и рислинг сгладят яркий вкус блюда с шалфеем и подчеркнут пикантные нюансы.\n\n🌿Петрушка + каберне совиньон и шенен блан. Нежно-пряный аромат со сладковатым вкусом идеально дополнять ярким вкусом каберне совиньон и шенен блан.\n\nФинал: думай вкусом\n\nКогда подбираешь напиток — не отталкивайся от названия блюда, смотри на вкус.\n\nЧто главнее: соус? специи? сладость? кислотность?\n\nИменно это и должно вести тебя к правильному выбору.\n\n🔸 Курица в сливочном соусе и курица в томатном — это два разных вкуса и они будут иметь разные винные пары.\n\n🔸 Салат с лимоном и салат с бальзамиком — тоже разные истории.\n\nВсё решают детали. А ты — тот, кто их должен замечать.\n\n❗Запомни: уверенное предложение = уважение + рост чека.\n\nЭто не про “впарить”. Это про вкус, заботу и грамотность.","images":["assets/remaining-courses/guru-44607-105822-0.jpg"],"links":[],"id":"105822"}],"outline":[{"type":"lesson","title":"Красные сорта","lessonIndex":0},{"type":"lesson","title":"Белые сорта","lessonIndex":1},{"type":"lesson","title":"Розовые Вина","lessonIndex":2},{"type":"lesson","title":"Игристые вина","lessonIndex":3},{"type":"lesson","title":"Сочетание вин с блюдами 🍽️","lessonIndex":4},{"type":"test","title":"Тест по винам"}],"testIds":["95485"]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
commit;
